// src/lib/mcp/orFilter.ts
function orIlike(value) {
  const raw = String(value ?? "").slice(0, 200);
  const likeEscaped = raw.replace(/[\\%_]/g, (c) => `\\${c}`);
  const quoted = `%${likeEscaped}%`.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
  return `"${quoted}"`;
}

